create extension if not exists pg_net; create extension if not exists pg_cron;
select cron.schedule('receipt-background-minute','* * * * *',$schedule$select net.http_post(url := 'https://mhgagjhwsjjjwwvopjgu.supabase.co/functions/v1/receipt-jobs',headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||(select token from public.receipt_worker_config where id=true)),body := '{"action":"work"}'::jsonb,timeout_milliseconds := 10000) where exists(select 1 from public.receipt_jobs where expires_at<=now() or status in ('queued','processing'));$schedule$);
